import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0044: Docs site as VitePress over docs/, served beside the landing page","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0044-docs-site-vitepress.md","filePath":"adrs/0044-docs-site-vitepress.md","lastUpdated":1789092097000}`),u={name:`adrs/0044-docs-site-vitepress.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[28]||=a(`<h1 id="adr-0044-docs-site-as-vitepress-over-docs-served-beside-the-landing-page" tabindex="-1">ADR-0044: Docs site as VitePress over <code>docs/</code>, served beside the landing page <a class="header-anchor" href="#adr-0044-docs-site-as-vitepress-over-docs-served-beside-the-landing-page" aria-label="Permalink to “ADR-0044: Docs site as VitePress over docs/, served beside the landing page”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-05 · Extends <a href="/adrs/0041-website-as-vite-vue-spa">ADR-0041</a>; retires the GitHub Wiki step in GITHUB-SETUP.md</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`The plan was to copy `,-1),l[2]||=c(`code`,null,`docs/wiki/*.md`,-1),l[3]||=i(` into the repo's GitHub Wiki at go-public. That gives a wiki, not documentation: no design control, weak search, a separate repo with no PR review, and pages Google barely indexes. Meanwhile `,-1),l[4]||=c(`code`,null,`docs/`,-1),l[5]||=i(` already holds the real reference material (engine contract, `,-1),r(m,{term:`theme`},{default:n(()=>[...l[0]||=[i(`themes`,-1)]]),_:1}),l[6]||=i(`, design, versioning, 43 ADRs) that a wiki would only duplicate. The bar is first-class docs in the Vue/Nuxt mould: markdown in, static site out, no database, light and dark, search, and the same identity as the landing page rather than a stock theme.`,-1)]),l[29]||=a(`<h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>VitePress</strong>, configured in <code>web/docs/.vitepress/</code>, with <code>srcDir</code> pointing at the repo&#39;s <strong><code>docs/</code></strong> folder. Built into <code>web/dist/docs/</code> by the existing Pages workflow and served at <code>&lt;site&gt;/docs/</code>.</p><p><strong>One source tree, no copies.</strong> <code>docs/wiki/*.md</code> are lifted to the site root by <code>rewrites</code> (<code>wiki/Home.md</code> → <code>/</code>, <code>wiki/Engines.md</code> → <code>/Engines</code>); reference docs and <code>adrs/</code> keep their paths; <code>PLAN.md</code> and <code>GITHUB-SETUP.md</code> are excluded (agent and owner material). The wiki pages stay GitHub-Wiki compatible on disk, <code>[[Page]]</code> links and <code>../blob/main/...</code> relative links included, so the wiki could be enabled later without editing them; nothing syncs it today.</p><p><strong>Four plugin layers, all in the repo:</strong></p>`,4),c(`ul`,null,[l[27]||=a(`<li><em>markdown-it</em>: <code>wikilinks.ts</code> turns <code>[[Getting Started]]</code> into <code>/Getting-Started</code> (GitHub&#39;s own slug rule, case kept); <code>repolinks.ts</code> resolves the wiki&#39;s GitHub-relative links (<code>../blob/main/docs/ENGINES.md</code> → the built page, <code>../releases/latest</code> → the repo) and rewrites any relative link that escapes <code>docs/</code> (<code>../../AGENT.md</code>) to a <code>blob/main</code> URL. Dead-link checking stays on; the build fails on a broken link.</li><li><em>Vite</em>: <code>goat-data.ts</code> serves <code>virtual:goat-data</code>: every ADR (number, title, status) parsed from <code>docs/adrs/</code>, and the release identity (<code>0.1 (Kid)</code> per VERSIONING.md) read from <code>release.json</code> when ADR-0040 lands, <code>project.yml</code> until then. The ADR sidebar and the nav release badge come from it, so neither goes stale.</li><li><em>build hooks</em>: <code>transformPageData</code> gives <code>wiki/Home.md</code> the <code>home</code> layout at build time, since frontmatter in the file would render as a table on GitHub.</li>`,3),c(`li`,null,[l[9]||=c(`em`,null,`theme`,-1),l[10]||=i(`: `,-1),l[11]||=c(`code`,null,`theme/`,-1),l[12]||=i(` extends the default theme: `,-1),r(m,{term:`caprine`},{default:n(()=>[...l[7]||=[i(`Caprine`,-1)]]),_:1}),l[13]||=i(),r(m,{term:`token`},{default:n(()=>[...l[8]||=[i(`tokens`,-1)]]),_:1}),l[14]||=i(` (Light for light, Midnight for dark) mapped onto `,-1),l[15]||=c(`code`,null,`--vp-c-*`,-1),l[16]||=i(`; nav, sidebar and cards go glass; the landing page's `,-1),l[17]||=c(`code`,null,`AuroraCanvas`,-1),l[18]||=i(` (WebGPU → WebGL2 → CSS, paused off-screen, frozen under Reduce Motion) is imported from `,-1),l[19]||=c(`code`,null,`web/src`,-1),l[20]||=i(` and pinned behind the page; the home hero is the landing page's hero condensed (`,-1),l[21]||=c(`code`,null,`Masthead`,-1),l[22]||=i(` + Midnight art + a local aurora, masked into the page); the wordmark cycles, page content reveals on navigation. `,-1),l[23]||=c(`code`,null,`<ReleaseBadge />`,-1),l[24]||=i(` and `,-1),l[25]||=c(`code`,null,`<AdrList />`,-1),l[26]||=i(` are global components any page can use.`,-1)])]),l[30]||=a(`<p><strong>Search</strong> is VitePress&#39;s local provider (MiniSearch index built at build time, queried in the browser). No Algolia, no runtime third-party requests, same rule as the landing page (ADR-0041).</p><p><strong>Tooling lives in <code>web/package.json</code></strong> (<code>vitepress@next</code>, the 2.0 line on Vite 8 to match the landing site), one <code>node_modules</code>, one lockfile, one CI cache. <code>npm run docs:dev</code> for local work, <code>npm run build:all</code> for what CI runs.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Public docs now include everything under <code>docs/</code> except the two excluded files. Writing there is writing for the site: keep prose free of bare <code>&lt;angle-brackets&gt;</code> outside code spans (Vue parses them) and make relative links resolve.</li><li><code>pages.yml</code> also triggers on <code>docs/**</code> and on the release identity files.</li><li>VitePress 2 is alpha. It is what vuejs.org runs on and the surface we use (config, markdown-it, theme slots) is the stable 1.x API, but pin bumps deliberately.</li><li>Design tokens are now hand-copied in three places (Swift, <code>main.css</code>, <code>goat.css</code>). Same escape hatch as ADR-0041: generate from <code>ThemeCatalog</code> JSON if it becomes a problem.</li><li><code>web/docs/.vitepress/{dist,cache}</code> are build outputs and git-ignored.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>GitHub Wiki (rejected: not first-class; see Context). Nuxt Content (rejected: excellent, and its SQLite is build-time/WASM so still static, but it brings Nuxt into a Vite SPA repo for nothing VitePress lacks). Roll our own on <code>unplugin-vue-markdown</code> inside the existing SPA (rejected: sidebar, outline, prev/next, search, code groups and dark mode would all be rebuilt; VitePress is that, maintained by the Vue team, and its plugin layers give the same freedom). Starlight, Docusaurus, MkDocs Material (rejected: wrong stack).</p>`,6)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};